# Count solutions for a, b in {0, 1, ..., 60}
for a in range(p):
    a_sq = (a * a) % p
    for b in range(p):
        b_sq = (b * b) % p
        r = (a_sq + b_sq) % p
        counts[r] += 1

print("--- Verification of R2(r) for a, b in {0, ..., 60} ---")
# Expected counts: R2(0) = 121, R2(r) = 60 for r != 0
print(f"R2(0) calculated: {counts[0]}")

